import {landingPage} from './marketing.js';
import {pricingPage,bindPricing} from './pricing.js';
import {pricingConfig} from './pricing-config.js';
import {appearanceControls,applyMotion} from './appearance.js';
import {appearancePanel} from './marketing-ui.js';
import {bindMotion} from './motion.js';
import {submitWaitlist} from './waitlist.js';
import {state,save,reset,people,statuses,projects,day,localDate,uid,activity,createTask,updateTask,createEvent} from './state.js';
import {icon,logo} from './icons.js';
const app=document.querySelector('#app'),overlay=document.querySelector('#overlay');
const ui={module:'home',channel:'launch',doc:'d3',meeting:'mt1',project:'All projects',board:true,side:true,calView:innerWidth<700?'day':'week',calDate:state.demoDate,calFocus:true,calTeam:true,activityUnread:false,query:'',status:'All statuses',owner:'Everyone',homeTeam:false,ai:null,tour:-1};
if(state.view&&typeof state.view==='object')for(const k of ['channel','doc','meeting','project','board','side','calView','calDate'])if(state.view[k]!==undefined)ui[k]=state.view[k];
const modules=[['home','Home'],['chat','Chat'],['calendar','Calendar'],['docs','Notes & Docs'],['meetings','Meetings'],['projects','Projects'],['activity','Activity'],['ai','Loop AI']];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials=n=>n.split(' ').map(x=>x[0]).join('').slice(0,2);
const avatar=(name='Alex Morgan',small=false)=>`<span class="avatar ${small?'small':''} av${Math.max(0,people.indexOf(name))}" title="${esc(name)}">${initials(name)}</span>`;
const btn=(label,action,cls='',ico='',data='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${data}>${ico?icon(ico,17):''}${label}</button>`;
const ib=(ico,label,action,data='')=>`<button type="button" class="icon-btn" title="${label}" aria-label="${label}" data-action="${action}" ${data}>${icon(ico)}</button>`;
const fmt=(date,opts={month:'short',day:'numeric'})=>new Date(date+'T12:00:00').toLocaleDateString('en-US',opts);
const time=t=>{const [h,m]=t.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`};
const due=d=>d===state.demoDate?'Today':d===day(1)?'Tomorrow':fmt(d);
const unread=()=>state.activity.filter(a=>!a.read).length;
function persist(){if(!save())toast('Browser storage is full. Changes remain in this session.')}
let toastTimer;function toast(message,undo){const el=document.querySelector('#toast');el.innerHTML=`${icon('check',17)}<span>${esc(message)}</span>${undo?'<button id="undo-toast">Undo</button>':''}`;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4500);if(undo)document.querySelector('#undo-toast').onclick=()=>{undo();el.classList.remove('show');render()}}
function go(module,id){if(module==='task'){taskDialog(id);return}if(module==='chat'&&id){const m=state.messages.find(x=>x.id===id);ui.channel=m?m.channel:id;if(m){state.activity.filter(a=>a.ref===id).forEach(a=>a.read=true);persist()}}if(module==='docs'&&id)ui.doc=id;if(module==='meetings'&&id)ui.meeting=id;if(module==='calendar'&&innerWidth<700)ui.calView='day';ui.module=module;ui.query='';if(location.pathname!=='/')history.pushState({},'', '/#app/'+module);else location.hash='app/'+module;render()}
function route(){if(location.hash.startsWith('#app')){ui.module=location.hash.split('/')[1]||'home';if(!modules.some(x=>x[0]===ui.module)&&ui.module!=='settings')ui.module='home'}render()}
function header(title,subtitle,actions=''){return `<div class="page-heading"><div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div><div class="heading-actions">${actions}</div></div>`}
function sectionHead(title,action='',label='View all'){return `<div class="section-head"><h2>${title}</h2>${action?btn(label,action,'text','',''):''}</div>`}
function taskRow(t){return `<div class="task-row"><button class="task-check ${t.status==='Done'?'checked':''}" aria-label="${t.status==='Done'?'Reopen':'Complete'} ${esc(t.title)}" data-action="toggle-task" data-id="${t.id}">${t.status==='Done'?icon('check',13):''}</button><button class="task-name" data-action="task" data-id="${t.id}"><strong>${esc(t.title)}</strong><span>${esc(t.project)}</span></button><span class="status-dot ${t.status.replaceAll(' ','-').toLowerCase()}"></span><span class="due">${due(t.due)}</span>${avatar(t.owner,true)}</div>`}
function eventRow(e){return `<button class="event-row" data-action="event" data-id="${e.id}"><span class="event-time">${time(e.time).split(' ')[0]}<small>${time(e.time).split(' ')[1]}</small></span><span class="event-bar"></span><span class="event-info"><strong>${esc(e.title)}</strong><small>${e.duration} min · ${e.attendees.length>1?e.attendees.slice(1).map(n=>n.split(' ')[0]).join(', '):'Just you'}</small></span>${icon(e.meetingId?'meetings':'headphones',17)}</button>`}
function home(){let tasks=state.tasks.filter(t=>t.status!=='Done'&&(ui.homeTeam||t.owner==='Alex Morgan'));let events=state.events.filter(e=>e.date===state.demoDate).sort((a,b)=>a.time.localeCompare(b.time));let copy=state.tasks.some(t=>t.source?.id==='m1');return `${header(`Good morning, ${esc(state.profile.split(' ')[0])}.`,`<span class="date-line">${fmt(state.demoDate,{weekday:'long',month:'long',day:'numeric'})}<span>•</span>Let’s make room for the work that matters.</span>`,btn('Take a 2-minute tour','tour','quiet','play'))}<div class="home-layout"><div class="home-primary"><section class="briefing"><div class="eyebrow">${icon('ai',17)} YOUR DAILY BRIEF <span class="subtle">Prepared for you</span></div><h2>A little clarity for the day ahead.</h2><p>${copy?'The onboarding copy has an owner. Your launch plan is moving forward.':'The launch is taking shape. Your design review is ready, and the onboarding copy still needs an owner.'} You have <b>${events.filter(e=>e.meetingId).length} meetings</b> today and <b>${tasks.length} open priorities</b>.</p><div class="brief-actions">${btn(copy?'See the launch plan':'Pick up the conversation','launch-source','primary','arrow')}${btn('Ask Loop AI','focus-ai','text','ai')}</div><div class="brief-orbit" aria-hidden="true"><span></span><span></span><span></span></div></section><section class="day-section"><div class="section-head"><div class="tabs"><button class="${!ui.homeTeam?'active':''}" data-action="my-day">My day <span>${state.tasks.filter(t=>t.owner==='Alex Morgan'&&t.status!=='Done').length}</span></button><button class="${ui.homeTeam?'active':''}" data-action="team-day">Team overview</button></div>${btn('New task','new-task','text','plus')}</div><div class="priority-label"><span>PRIORITIES</span><span>DUE</span></div>${tasks.length?tasks.map(taskRow).join(''):'<div class="empty">You’re all caught up. A little space for what’s next.</div>'}</section><section class="attention">${sectionHead('Worth your attention','nav-chat','Open chat '+icon('arrow',14))}<button class="conversation-card" data-action="launch-source">${avatar('Maya Chen')}<span><span class="conversation-meta"><b>Maya Chen</b><span>in #launch</span><small>9:14 AM</small></span><strong>One last piece of the launch story.</strong><p>Can someone take a first pass at the onboarding copy?</p><span class="inline-link">3 messages · Open conversation ${icon('arrow',14)}</span></span><span class="unread-dot"></span></button></section><section>${sectionHead('Keep the context close','nav-docs','All documents '+icon('arrow',14))}<div class="doc-cards">${state.docs.filter(d=>d.favorite).slice(0,3).map(d=>`<button class="doc-card" data-action="doc" data-id="${d.id}"><span class="document-icon">${icon('docs',22)}</span><strong>${esc(d.title)}</strong><small>Loop workspace</small></button>`).join('')}</div></section></div><aside class="home-secondary"><section class="agenda-panel">${sectionHead('On your calendar','nav-calendar','Open '+icon('arrow',14))}<p class="muted small-text">TODAY <span class="float-right">${Intl.DateTimeFormat().resolvedOptions().timeZone.replaceAll('_',' ')}</span></p>${events.map(eventRow).join('')}<div class="agenda-footer">${icon('sun',17)} A little breathing room after 3 PM.</div></section><section class="suggestion-panel"><div class="eyebrow">${icon('ai',17)} A STEP AHEAD</div><h3>Bring the right people together.</h3><p>Find a launch review time after the copy is ready. I can prepare an invite for you to review.</p>${btn('Review suggestion','schedule-ai','quiet','arrow')}<small>Simulated AI · You’re always in control</small></section><section class="team-feed">${sectionHead('Around the team','nav-activity','View all')}${state.activity.slice(0,3).map(a=>`<button class="feed-row" data-action="activity-open" data-id="${a.id}"><span class="feed-dot"></span><span>${esc(a.title)}<small>${a.time}</small></span></button>`).join('')}</section><div class="home-note">${logo}<span>A place for everything.<br>A little more space for you.</span></div></aside></div>`}
function sidebar(){let body='';if(ui.module==='home')body=`<div class="sidebar-label">YOUR WORKSPACE</div><button class="side-link selected" data-action="nav-home">${icon('sun',17)} Overview</button><button class="side-link" data-action="nav-activity">${icon('activity',17)} Your activity <span class="count">${unread()}</span></button><div class="sidebar-label spaced">PINNED</div>${state.docs.filter(d=>d.favorite).map(d=>`<button class="side-link" data-action="doc" data-id="${d.id}">${icon('docs',16)}${esc(d.title)}</button>`).join('')}<div class="sidebar-label spaced">YOUR PROJECTS</div>${projects.slice(0,3).map((p,i)=>`<button class="side-link" data-action="project" data-id="${p}"><span class="project-dot p${i}"></span>${p}</button>`).join('')}<div class="sidebar-bottom"><div class="team-avatars">${people.slice(1,5).map(n=>avatar(n,true)).join('')}</div><p>Good work happens together.</p><small>Loop · Fictional demo team</small></div>`;
else if(ui.module==='chat')body=`<label class="side-search">${icon('search',15)}<input aria-label="Filter conversations" id="channel-filter" placeholder="Find a conversation"></label><button class="side-link ${ui.channel==='saved'?'selected':''}" data-action="channel" data-id="saved">${icon('bookmark',17)}Saved messages</button><div class="sidebar-label spaced">CHANNELS</div>${['general','product','design','launch','customer-feedback'].map(c=>`<button class="side-link ${ui.channel===c?'selected':''}" data-action="channel" data-id="${c}">${icon('hash',17)}${c}${c==='launch'?'<span class="count">'+state.activity.filter(a=>!a.read&&a.ref==='m1').length+'</span>':''}</button>`).join('')}<div class="sidebar-label spaced">DIRECT MESSAGES</div>${people.slice(1).map(n=>`<button class="side-link ${ui.channel===n?'selected':''}" data-action="channel" data-id="${n}">${avatar(n,true)}${n}</button>`).join('')}`;
else if(ui.module==='docs')body=`${btn('New document','new-doc','quiet full','plus')}<div class="sidebar-label spaced">FAVORITES</div>${state.docs.filter(d=>d.favorite).map(d=>docSide(d)).join('')}<div class="sidebar-label spaced">WORKSPACE PAGES</div>${state.docs.filter(d=>!d.parent).map(d=>docSide(d)+state.docs.filter(c=>c.parent===d.id).map(c=>docSide(c,true)).join('')).join('')}`;
else if(ui.module==='projects')body=`${btn('New task','new-task','quiet full','plus')}<div class="sidebar-label spaced">PROJECTS</div>${['All projects',...projects].map((p,i)=>`<button class="side-link ${ui.project===p?'selected':''}" data-action="project" data-id="${p}"><span class="project-dot p${i%3}"></span>${p}</button>`).join('')}<div class="sidebar-label spaced">AT A GLANCE</div>${projects.map(p=>{let ts=state.tasks.filter(t=>t.project===p),n=ts.filter(t=>t.status==='Done').length;return `<div class="project-progress"><span>${p}<small>${n}/${ts.length}</small></span><div class="progress"><i style="width:${ts.length?n/ts.length*100:0}%"></i></div></div>`}).join('')}`;
else if(ui.module==='calendar')body=`${btn('New event','new-event','primary full','plus')}<div class="mini-calendar"><div>${fmt(ui.calDate,{month:'long',year:'numeric'})}</div><div class="mini-grid">${['M','T','W','T','F','S','S'].map(d=>`<small>${d}</small>`).join('')}${miniDays()}</div></div><div class="sidebar-label">MY CALENDARS</div><label class="check-label"><input id="cal-team" type="checkbox" ${ui.calTeam?'checked':''}> Loop meetings</label><label class="check-label"><input id="cal-focus" type="checkbox" ${ui.calFocus?'checked':''}> Focus time</label><div class="sidebar-label spaced">TIME ZONE</div><p class="muted small-text">${Intl.DateTimeFormat().resolvedOptions().timeZone}</p>`;
else if(ui.module==='meetings')body=`<div class="sidebar-label">UPCOMING & RECENT</div>${state.meetings.map(m=>{let e=state.events.find(e=>e.id===m.eventId);return `<button class="side-link meeting-link ${m.id===ui.meeting?'selected':''}" data-action="meeting" data-id="${m.id}">${icon('meetings',17)}<span>${esc(e?.title||'Meeting')}<small>${e?fmt(e.date)+' · '+time(e.time):''}</small></span></button>`}).join('')}`;
else if(ui.module==='ai')body=`<div class="sidebar-label">YOUR COORDINATION SPACE</div><p class="sidebar-copy">A little context.<br>A clearer next step.</p>${[['focus','Today’s priorities'],['summary','Launch discussion'],['schedule','Find a review time'],['draft','Draft a team update'],['blockers','Launch blockers']].map(([id,s])=>`<button class="side-link" data-action="ai-intent" data-id="${id}">${icon('ai',17)}${s}</button>`).join('')}<div class="sidebar-bottom"><small>Simulated AI<br>Built-in scenarios, real local changes.<br>Nothing is applied without your review.</small></div>`;
else body=`<div class="sidebar-label">NORTHSTAR</div>${btn('Workspace overview','nav-home','side-link','home')}${btn('Activity & notifications','nav-activity','side-link','activity')}${btn('Preferences','nav-settings','side-link','settings')}`;
return `<aside class="context-sidebar"><div class="workspace-switch"> <span class="workspace-emblem">✦</span><span>Loop<small>Demo workspace</small></span>${ib('down','Workspace settings','nav-settings')}</div>${body}</aside>`}
function docSide(d,nested=false){return `<button class="side-link ${nested?'nested':''} ${ui.doc===d.id?'selected':''}" data-action="doc" data-id="${d.id}">${icon('docs',16)}${esc(d.title)}</button>`}
function shell(){return `<div class="workspace ${ui.side?'':'sidebar-collapsed'}"><nav class="global-rail" aria-label="Main navigation"><a class="brand-mark" href="/" aria-label="Loop landing page">${logo}</a><div class="rail-links">${modules.map(([id,label])=>`<button class="rail-button ${ui.module===id?'active':''} ${id==='ai'?'ai-rail':''}" title="${label}" aria-label="${label}" aria-current="${ui.module===id?'page':'false'}" data-action="nav-${id}">${icon(id,21)}${id==='activity'&&state.notifications&&unread()?'<span class="rail-dot"></span>':''}<span class="rail-tooltip">${label}</span></button>`).join('')}</div><div class="rail-bottom">${ib('settings','Settings','nav-settings')}<button class="profile-button" data-action="nav-settings" aria-label="Profile">${avatar(state.profile,true)}</button></div></nav>${sidebar()}<div class="workspace-body"><header class="topbar"><div class="breadcrumb">${ib('panel','Toggle sidebar','sidebar')}<span>Workspace</span>${icon('chevron',12)}<b>${modules.find(x=>x[0]===ui.module)?.[1]||'Settings'}</b></div><button class="global-search" data-action="search">${icon('search',16)}<span>Search anything</span><kbd>⌘ K</kbd></button><div class="top-actions"><span class="demo-label"><i></i>Interactive demo</span>${ib('plus','Quick create','quick-create')}${ib('activity','Notifications','notifications')}</div></header><main id="main" class="main-content ${ui.module==='chat'?'chat-main':''}">${view()}</main></div></div>${ui.tour>=0?tourHtml():''}`}
function view(){return ({home,chat,calendar,docs,meetings,projects:projectView,activity:activityView,ai:aiView,settings}[ui.module]||home)()}
function render(){state.view=Object.fromEntries(['channel','doc','meeting','project','board','side','calView','calDate'].map(k=>[k,ui[k]]));save();document.body.classList.toggle('reduce-motion',state.reduced);applyMotion(state.reduced);const inApp=location.hash.startsWith('#app');document.title=inApp?'Loop — '+(modules.find(m=>m[0]===ui.module)?.[1]||'Settings'):(location.pathname.replace(/\/$/,'')==='/pricing'?'Loop — Plans for your next chapter':'Loop — Work, in harmony.');app.innerHTML=inApp?shell():location.pathname.replace(/\/$/,'')==='/pricing'?pricingPage():landing();bindEditor();bindPricing();bindMotion();if(ui.module==='chat'&&location.hash.startsWith('#app'))document.querySelector('.messages')?.scrollTo(0,99999)}
function miniDays(){let date=new Date(ui.calDate+'T12:00:00');date.setDate(1);let start=(date.getDay()+6)%7;let end=new Date(date.getFullYear(),date.getMonth()+1,0).getDate();return '<span></span>'.repeat(start)+Array.from({length:end},(_,i)=>{let d=localDate(new Date(date.getFullYear(),date.getMonth(),i+1));return `<button class="${d===ui.calDate?'selected':''}" data-action="cal-date" data-id="${d}">${i+1}</button>`}).join('')}
function chat(){const msgs=state.messages.filter(m=>ui.channel==='saved'?m.saved:m.channel===ui.channel);return `<div class="chat-heading"><div><h1>${ui.channel==='saved'?icon('bookmark'):ui.channel.includes(' ')?avatar(ui.channel):icon('hash')} ${esc(ui.channel)}</h1><p>${ui.channel==='launch'?'One thoughtful launch. Every detail connected.':'A shared space to move the work forward.'}</p></div><div class="heading-actions">${btn('Summarize','summarize-chat','quiet','ai')}<div class="team-avatars">${people.slice(0,3).map(p=>avatar(p,true)).join('')}</div></div></div><div class="channel-banner">${icon('link',16)} Connected to <button data-action="project" data-id="Website launch">Website launch</button><span>·</span><button data-action="doc" data-id="d3">Q4 launch brief ${icon('arrow',13)}</button></div><div class="messages"><div class="timeline-date">${fmt(state.demoDate,{weekday:'long',month:'long',day:'numeric'})}</div>${msgs.length?msgs.map(messageHtml).join(''):'<div class="empty">'+(ui.channel==='saved'?'Save a message to keep it close.':'Start a conversation. A little context goes a long way.')+'</div>'}</div>${ui.channel!=='saved'?`<form id="message-form" class="composer"><textarea aria-label="Message" name="body" placeholder="Message ${ui.channel.includes(' ')?'':'#'}${esc(ui.channel)}" required>${esc(state.drafts[ui.channel]||'')}</textarea><div><span>Enter to send · Shift + Enter for a new line</span><button class="btn primary" type="submit">Send ${icon('send',16)}</button></div></form>`:''}`}
function messageHtml(m){let task=state.tasks.find(t=>t.source?.id===m.id);return `<article class="message" id="message-${m.id}">${avatar(m.author)}<div class="message-content"><div class="message-by"><strong>${esc(m.author)}</strong><span>${m.author==='Maya Chen'?'Design':m.author==='Jordan Lee'?'Engineering':''}</span><time>${esc(m.time)}</time></div><p>${esc(m.body).replaceAll('\n','<br>')}</p>${m.links?.map(l=>`<button class="source-chip" data-action="source" data-type="${l.type}" data-id="${l.id}">${icon(l.type,14)}${esc(l.label)}</button>`).join('')||''}${task?`<button class="source-chip" data-action="task" data-id="${task.id}">${icon('check',14)}Task · ${esc(task.title)}</button>`:''}<div class="message-footer"><button class="reaction ${m.reactions.includes('Alex Morgan')?'reacted':''}" data-action="react" data-id="${m.id}" aria-label="${m.reactions.includes('Alex Morgan')?'Remove':'Add'} appreciation">${icon('smile',15)}${m.reactions.length||'React'}</button><button data-action="thread" data-id="${m.id}">${icon('chat',14)}${m.replies.length?m.replies.length+' replies':'Reply'}</button><button data-action="message-task" data-id="${m.id}">${icon('plus',14)}Create task</button><button data-action="save-message" data-id="${m.id}" aria-label="${m.saved?'Unsave':'Save'} message">${icon('bookmark',14)}${m.saved?'Saved':'Save'}</button><button data-action="link-message" data-id="${m.id}">${icon('link',14)}Link</button></div></div></article>`}
function projectView(){let ts=state.tasks.filter(t=>(ui.project==='All projects'||t.project===ui.project)&&(ui.status==='All statuses'||t.status===ui.status)&&(ui.owner==='Everyone'||t.owner===ui.owner)&&t.title.toLowerCase().includes(ui.query.toLowerCase()));let all=state.tasks.filter(t=>ui.project==='All projects'||t.project===ui.project),done=all.filter(t=>t.status==='Done').length;return `${header(esc(ui.project),'A shared plan. A clear next step.',btn('New task','new-task','primary','plus'))}<div class="project-summary"><span class="project-symbol">${icon('projects',25)}</span><span><strong>${done} of ${all.length} tasks complete</strong><small>${all.filter(t=>t.status==='In progress').length} in progress · ${all.filter(t=>t.status==='In review').length} awaiting review</small></span><div class="progress"><i style="width:${all.length?done/all.length*100:0}%"></i></div><b>${all.length?Math.round(done/all.length*100):0}%</b><div class="team-avatars">${people.slice(0,4).map(p=>avatar(p,true)).join('')}</div></div><div class="view-toolbar"><div class="segmented">${btn('Board','board',ui.board?'active':'','board')}${btn('List','list',!ui.board?'active':'','list')}</div><label class="search-field">${icon('search',16)}<input id="task-search" aria-label="Search tasks" placeholder="Search tasks" value="${esc(ui.query)}"></label><select id="status-filter" aria-label="Filter by status">${['All statuses',...statuses].map(s=>`<option ${s===ui.status?'selected':''}>${s}</option>`).join('')}</select><select id="owner-filter" aria-label="Filter by assignee">${['Everyone',...people].map(s=>`<option ${s===ui.owner?'selected':''}>${s}</option>`).join('')}</select></div>${ui.board?`<div class="board">${statuses.map((s,i)=>`<section class="board-column"><div class="board-title"><span class="status-dot ${s.replaceAll(' ','-').toLowerCase()}"></span><h2>${s}</h2><span>${ts.filter(t=>t.status===s).length}</span>${ib('plus','Add '+s+' task','new-task',`data-status="${s}"`)}</div>${ts.filter(t=>t.status===s).map(t=>`<button class="task-card" data-action="task" data-id="${t.id}"><span class="task-project">${esc(t.project)}</span><strong>${esc(t.title)}</strong><div class="task-tags">${t.priority==='High'?'<span class="priority-high">'+icon('flag',12)+' High priority</span>':''}${t.source?icon(t.source.type==='chat'?'chat':t.source.type==='meetings'?'meetings':'docs',14):''}</div><footer><span>${icon('calendar',13)}${due(t.due)}</span>${avatar(t.owner,true)}</footer></button>`).join('')}${btn('Add task','new-task','add-card','plus',`data-status="${s}"`)}</section>`).join('')}</div>`:`<section class="list-panel">${ts.length?ts.map(taskRow).join(''):'<div class="empty">No tasks match these filters.</div>'}</section>`}`}
function calendar(){let date=new Date(ui.calDate+'T12:00:00'),dates=[];if(ui.calView==='week'){date.setDate(date.getDate()-(date.getDay()+6)%7);dates=Array.from({length:7},(_,i)=>{let d=new Date(date);d.setDate(d.getDate()+i);return localDate(d)})}else if(ui.calView==='month'){date.setDate(1);date.setDate(date.getDate()-(date.getDay()+6)%7);dates=Array.from({length:42},(_,i)=>{let d=new Date(date);d.setDate(d.getDate()+i);return localDate(d)})}else dates=[ui.calDate];const events=state.events.filter(e=>e.calendar==='focus'?ui.calFocus:ui.calTeam);const visibleEvents=events.filter(e=>dates.includes(e.date));const startHour=Math.min(8,...visibleEvents.map(e=>Number(e.time.split(':')[0]))),endHour=Math.min(24,Math.max(19,...visibleEvents.map(e=>Math.ceil(Number(e.time.split(':')[0])+Number(e.time.split(':')[1])/60+e.duration/60))));const hours=Array.from({length:endHour-startHour},(_,i)=>i+startHour);return `${header(fmt(ui.calDate,{month:'long',year:'numeric'}),'Time for your team. Space for your focus.',btn('New event','new-event','primary','plus'))}<div class="view-toolbar calendar-toolbar">${btn('Today','cal-today','quiet')}${ib('chevron','Previous period','cal-prev','style="transform:rotate(180deg)"')}${ib('chevron','Next period','cal-next')}<span class="muted">${ui.calView==='week'?fmt(dates[0])+' – '+fmt(dates[6]):fmt(ui.calDate,{weekday:'long',day:'numeric',month:'short'})}</span><div class="segmented push-right">${['day','week','month'].map(v=>btn(v[0].toUpperCase()+v.slice(1),'cal-view',ui.calView===v?'active':'','',`data-id="${v}"`)).join('')}</div></div><p class="calendar-zone">${Intl.DateTimeFormat().resolvedOptions().timeZone} · Click a time to make room for something.</p>${ui.calView==='month'?`<div class="month-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(n=>`<div class="month-label">${n}</div>`).join('')}${dates.map(d=>`<div class="month-cell ${d===state.demoDate?'today':''}"><button data-action="new-event" data-date="${d}" aria-label="New event on ${d}">${Number(d.slice(-2))}</button>${events.filter(e=>e.date===d).map(e=>`<button class="month-event" data-action="event" data-id="${e.id}">${time(e.time)} ${esc(e.title)}</button>`).join('')}</div>`).join('')}</div>`:`<div class="calendar-scroll"><div class="week-calendar" style="--days:${dates.length}"><div class="week-head"><span></span>${dates.map(d=>`<div class="${d===state.demoDate?'today':''}"><small>${fmt(d,{weekday:'short'})}</small><b>${Number(d.slice(-2))}</b></div>`).join('')}</div><div class="week-body"><div class="hour-labels">${hours.map(h=>`<span>${h%12||12} ${h>=12?'PM':'AM'}</span>`).join('')}</div>${dates.map(d=>`<div class="day-column">${hours.map(h=>`<button class="time-slot" data-action="new-event" data-date="${d}" data-time="${String(h).padStart(2,'0')}:00" aria-label="Create event ${d} at ${h}:00"></button>`).join('')}${events.filter(e=>e.date===d).map(e=>{let [h,m]=e.time.split(':').map(Number);return `<button class="calendar-event ${e.calendar==='focus'?'focus-event':''}" style="top:${Math.max(0,(h-startHour)*64+m/60*64)}px;height:${Math.max(38,e.duration/60*64)}px" data-action="event" data-id="${e.id}"><strong>${esc(e.title)}</strong><small>${time(e.time)}</small></button>`}).join('')}</div>`).join('')}</div></div></div>`}`}
function safeHtml(html){let t=document.createElement('template');t.innerHTML=html;t.content.querySelectorAll('*').forEach(el=>{if(!['P','H1','H2','H3','UL','OL','LI','B','STRONG','I','EM','U','BLOCKQUOTE','A','BR','DIV','SPAN'].includes(el.tagName)){el.replaceWith(...el.childNodes);return}if(el.tagName==='P'&&/^☐ |^☑ /.test(el.textContent)){el.dataset.check=el.textContent.startsWith('☑')?'true':'false';el.textContent=el.textContent.slice(2)}for(let a of [...el.attributes])if(!((el.tagName==='P'&&a.name==='data-check'&&['true','false'].includes(a.value))||(el.tagName==='A'&&a.name==='href'&&/^(https?:|mailto:|#)/i.test(a.value))))el.removeAttribute(a.name);if(el.tagName==='A'){el.setAttribute('target','_blank');el.setAttribute('rel','noopener noreferrer')}});return t.innerHTML}
function docs(){const d=state.docs.find(d=>d.id===ui.doc)||state.docs[0];ui.doc=d.id;return `<div class="doc-topline"><span>Workspace ${icon('chevron',12)} ${d.parent?'Launch & company':'Knowledge'} ${icon('chevron',12)} <b>${esc(d.title)}</b></span><div>${ib('star',d.favorite?'Remove favorite':'Favorite document','favorite-doc',`data-id="${d.id}"`)}${btn('Comments','doc-comments','quiet','chat')}${btn('Find page','search','quiet','search')}</div></div><article class="document"><div class="doc-kicker">${icon('docs',32)}</div><input class="doc-title" id="doc-title" aria-label="Document title" value="${esc(d.title)}"><div class="doc-meta">${avatar('Alex Morgan',true)}<span>Alex Morgan</span><span>·</span><span id="save-state">Saved in this browser</span><span class="push-right">${state.docs.find(x=>x.id===d.parent)?.title||'Loop'}</span></div><div class="editor-toolbar" role="toolbar" aria-label="Text formatting">${[['bold','B'],['italic','I'],['h2','H2'],['insertUnorderedList','• List'],['insertOrderedList','1. List'],['checklist','☐'],['blockquote','Quote'],['link','Link']].map(([a,l])=>`<button data-action="format" data-id="${a}" aria-label="Format ${a}">${l}</button>`).join('')}<span class="push-right"></span>${btn('Create task','doc-task','text','plus')}</div><div id="doc-editor" class="doc-editor" contenteditable="true" role="textbox" aria-label="Document content" aria-multiline="true">${safeHtml(d.content)}</div><div class="doc-bottom">${icon('link',15)} Your knowledge stays connected. ${btn('Open Website launch','project','text','arrow','data-id="Website launch"')}</div></article>`}
function bindEditor(){const el=document.querySelector('#doc-editor');if(el){function checks(){el.querySelectorAll('p[data-check]').forEach(p=>{if(p.querySelector('.doc-check-toggle'))return;let b=document.createElement('button');b.type='button';b.className='doc-check-toggle';b.contentEditable='false';b.setAttribute('role','checkbox');b.setAttribute('aria-label',p.textContent);b.setAttribute('aria-checked',p.dataset.check);p.prepend(b)})}checks();el.addEventListener('input',()=>{state.docs.find(d=>d.id===ui.doc).content=safeHtml(el.innerHTML);persist();document.querySelector('#save-state').textContent='All changes saved locally';checks()});el.addEventListener('paste',e=>{e.preventDefault();document.execCommand('insertText',false,e.clipboardData.getData('text/plain'))});document.querySelectorAll('[data-action="format"]').forEach(b=>b.addEventListener('mousedown',e=>e.preventDefault()))}}
function meetings(){const m=state.meetings.find(m=>m.id===ui.meeting)||state.meetings[0];ui.meeting=m.id;const e=state.events.find(e=>e.id===m.eventId);return `${header(esc(e.title),`${fmt(e.date,{weekday:'long',month:'long',day:'numeric'})} · ${time(e.time)} · ${e.duration} minutes`,btn('Edit event','event','quiet','calendar',`data-id="${e.id}"`)+btn('Open room preview','room','primary','meetings'))}<div class="meeting-layout"><div><section class="meeting-hero"><div class="eyebrow">A GOOD MEETING STARTS WITH CONTEXT</div><h2>Get aligned.<br>Leave with a next step.</h2><p>${esc(e.description)}</p><div class="attendees">${e.attendees.map(n=>`<span>${avatar(n,true)}${n.split(' ')[0]}</span>`).join('')}</div></section><section class="surface meeting-section">${sectionHead('The agenda')}<ol class="agenda-list">${m.agenda.map(a=>`<li>${esc(a)}</li>`).join('')}</ol><button class="linked-document" data-action="doc" data-id="${m.docId}">${icon('docs',20)}<span>${esc(state.docs.find(d=>d.id===m.docId)?.title||'Launch brief')}<small>Linked context</small></span>${icon('arrow',16)}</button></section><section class="surface meeting-section">${sectionHead('Meeting notes')}<p class="muted small-text">Prepared sample notes · Edit them for your demo</p><textarea class="meeting-notes" id="meeting-notes" aria-label="Meeting notes">${esc(m.notes)}</textarea></section></div><div><section class="surface summary-panel"><div class="eyebrow">${icon('ai',17)} FROM DISCUSSION TO DIRECTION</div><h2>Keep the momentum.</h2><p>Turn the prepared meeting notes into a clear summary and reviewable follow-through.</p>${!m.summary?btn('Generate sample summary','generate-summary','primary','ai'):summaryHtml(m)}</section><section class="meeting-section">${sectionHead('Action items')}<div>${m.actionTaskIds.length?m.actionTaskIds.map(id=>{let t=state.tasks.find(t=>t.id===id);return t?taskRow(t):''}).join(''):'<p class="muted">Approved follow-ups will appear here and in Projects.</p>'}</div></section></div></div>`}
function summaryHtml(m){return `<div class="generated-summary"><span class="badge">Prepared sample · Ready for review</span><h3>Decisions</h3><p>Keep onboarding focused on one useful action. The visual direction is ready; copy remains the final dependency.</p><h3>Suggested follow-up</h3><p>Validate the mobile onboarding flow with the design team.</p><div class="suggestion-owner">${avatar('Alex Morgan',true)} Alex Morgan · ${due(day(1))}</div>${m.actionTaskIds.length?'<span class="success-text">'+icon('check',16)+' Applied · Task created</span>':btn('Review follow-up task','meeting-task','primary','plus')}<small>Review and edit the details before creating a task.</small></div>`}
function activityView(){const items=state.activity.filter(a=>!ui.activityUnread||!a.read);return `${header('Your activity','The important updates, with the context to act.',btn('Mark all as read','read-all','quiet','check'))}<div class="tabs activity-tabs">${btn('All updates','activity-all',!ui.activityUnread?'active':'')}${btn('Unread · '+unread(),'activity-unread',ui.activityUnread?'active':'')}</div><div class="activity-list">${items.map(a=>`<div class="activity-item ${a.read?'read':''}"><span class="activity-icon">${icon(a.type==='task'?'projects':a.type,20)}</span><button data-action="activity-open" data-id="${a.id}"><strong>${esc(a.title)}</strong><span>${esc(a.detail)}</span></button><time>${esc(a.time)}</time>${ib(a.read?'check':'more',a.read?'Mark unread':'Mark as read','read-one',`data-id="${a.id}"`)}</div>`).join('')||'<div class="empty">You’re all caught up.</div>'}</div>`}
const prompts=[['focus','What should I focus on today?'],['summary','Summarize the launch discussion.'],['tasks','Turn these meeting actions into tasks.'],['schedule','Find time for a launch review.'],['draft','Draft an update for the team.'],['blockers','What is blocking the website launch?']];
function aiView(){return `${header('A little help. A clearer day.','Loop AI connects the context, so you can choose the next step.','<span class="badge">Simulated AI</span>')}<div class="ai-workspace"><div class="ai-symbol">${icon('ai',34)}</div><h2>What would you like to move forward?</h2><p class="muted">Your conversations, plans, and knowledge. One shared context.</p><div class="prompt-grid">${prompts.map(([id,p])=>btn(p,'ai-intent','prompt','arrow',`data-id="${id}"`)).join('')}</div>${ui.ai?aiResponse(ui.ai):''}<form id="ai-form" class="ai-composer"><input name="prompt" aria-label="Ask Loop AI" placeholder="Ask about your work…" required><button type="submit" class="icon-btn" aria-label="Send prompt">${icon('arrow')}</button></form><p class="ai-disclaimer">Built-in demo scenarios. Nothing is applied without your approval.</p></div>`}
function scheduleProposal(){let copy=state.tasks.find(t=>t.source?.id==='m1');let date=copy&&copy.due>day()?copy.due:day(1);for(let i=0;i<30;i++){for(let hour of [15,16,14,13,11,10]){let start=hour*60;if(!state.events.some(e=>e.date===date&&Number(e.time.split(':')[0])*60+Number(e.time.split(':')[1])<start+30&&start<Number(e.time.split(':')[0])*60+Number(e.time.split(':')[1])+e.duration))return {date,time:String(hour).padStart(2,'0')+':00'};}let d=new Date(date+'T12:00:00');d.setDate(d.getDate()+1);date=localDate(d)}return {date:day(31),time:'15:00'}}
function aiResponse(intent){let copy=state.tasks.find(t=>t.source?.id==='m1'),applied=state.applied.includes(intent);let scheduled=state.events.find(e=>e.id===state.actionRefs?.schedule)||state.events.find(e=>e.title==='Launch copy review');let text={focus:`Start with design approval${copy?', then check in on '+copy.title:'. The onboarding copy also needs an owner'}. Your launch review is at ${time(state.events.find(e=>e.id==='e1').time)}. You have ${state.tasks.filter(t=>t.owner==='Alex Morgan'&&t.status!=='Done').length} open tasks.`,summary:'The launch direction is ready. Maya asked for an owner to revise the onboarding copy, and Jordan is waiting on that copy to complete the welcome screen.',blockers:copy?`The copy is assigned to ${copy.owner} and is ${copy.status.toLowerCase()}. Design approval is ${state.tasks.find(t=>t.id==='t1').status.toLowerCase()}. Resolve those dependencies before the final launch review.`:'The onboarding copy needs an owner. Jordan’s welcome screen depends on it, and the launch direction still needs design approval.',schedule:applied&&scheduled?`Your approved review is scheduled for ${fmt(scheduled.date)} at ${time(scheduled.time)}. The event and linked meeting are saved in your local workspace.`:`A 30-minute review on ${fmt(scheduleProposal().date)} at ${time(scheduleProposal().time)} gives the team time for the copy pass${copy?' due '+fmt(copy.due):''}. This slot is free in the local demo calendar; external availability isn’t checked.`,tasks:'The launch review suggests validating the mobile onboarding flow. Review the owner and due date before creating the follow-up.',draft:'Here is a draft for #launch, based on the current launch plan. You can edit it before posting locally.',unknown:'I can help with today’s priorities, the launch discussion, meeting follow-ups, a review time, a team update, or launch blockers. Try one of the examples above.'}[intent];return `<section class="ai-response"><div class="eyebrow">${icon('ai',18)} LOOP AI <span class="badge">${applied?'Applied':'Suggested'}</span></div><p>${esc(text)}</p><div class="ai-sources">${btn('#launch','launch-source','source-chip','chat')}${btn('Launch brief','doc','source-chip','docs','data-id="d3"')}</div>${['schedule','tasks','draft'].includes(intent)?`<div class="proposed-action"><span>${icon(intent==='schedule'?'calendar':intent==='tasks'?'projects':'chat',21)}</span><div><strong>${intent==='schedule'?'Launch copy review':intent==='tasks'?'Validate the mobile onboarding flow':'Launch readiness update'}</strong><small>${applied?'Confirmed in your local workspace':'Awaiting review · You decide what happens next'}</small></div>${applied?icon('check'):btn('Review','ai-review','primary','arrow',`data-id="${intent}"`)}</div>`:intent!=='unknown'?btn('Open source conversation','launch-source','quiet','arrow'):''}</section>`}
function settings(){return `${header('Make yourself at home.','An independent workspace. A few preferences to make it yours.')}<div class="settings-content"><form id="settings-form" class="surface settings-section"><h2>Your profile</h2><label>Display name<input name="name" value="${esc(state.profile)}" required maxlength="60"></label><label class="check-label"><input name="reduced" type="checkbox" ${state.reduced?'checked':''}> Reduce motion</label><label class="check-label"><input name="notifications" type="checkbox" ${state.notifications?'checked':''}> Show activity notifications</label><div class="settings-appearance"><h3>Your point of view</h3>${appearanceControls()}</div><button class="btn primary" type="submit">Save preferences</button></form><section class="surface settings-section"><h2>Loop workspace</h2><p>6 fictional demo participants · Local browser storage</p><p class="muted">Demo date: ${fmt(state.demoDate,{month:'long',day:'numeric',year:'numeric'})}<br>Time zone: ${Intl.DateTimeFormat().resolvedOptions().timeZone}</p><h3>Connected tools</h3><p class="muted">Preview how your existing tools could share context.</p>${['Slack','Google Calendar','Google Drive'].map(n=>`<button class="integration" data-action="integration" data-id="${n}">${icon('link',18)}<b>${n}</b><span>Planned integration</span>${icon('arrow',16)}</button>`).join('')}<div class="reset-section"><h3>A fresh start</h3><p class="muted">Restore the seeded demo. This replaces your local workspace edits.</p>${btn('Reset demo data','reset','quiet','undo')}</div></section></div>`}
let lastFocus=null,dialogCleanup=null,closeTimer=null;
function closeDialog(animate=false){clearTimeout(closeTimer);if(dialogCleanup){dialogCleanup();dialogCleanup=null}const closing=overlay.querySelector('dialog');if(animate&&closing&&document.documentElement.dataset.reduced!=='true'){closing.classList.add('is-closing');closeTimer=setTimeout(()=>closeDialog(),140);return}overlay.querySelector('dialog')?.close();overlay.innerHTML='';if(lastFocus?.isConnected)lastFocus.focus();else document.querySelector('.global-search, .landing-nav .btn')?.focus()}
function dialog(title,body,wide=false){closeDialog();lastFocus=document.activeElement;overlay.innerHTML=`<dialog class="modal ${wide?'wide':''}"><div class="modal-head"><h2>${title}</h2>${ib('close','Close dialog','close')}</div><div class="modal-body">${body}</div></dialog>`;let d=overlay.querySelector('dialog');d.setAttribute('aria-label',title.replace(/<[^>]*>/g,''));d.showModal();d.addEventListener('click',e=>{if(e.target===d&&e.clientX!==0){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(true)}});d.addEventListener('cancel',e=>{e.preventDefault();closeDialog(true)})}
function formSelect(name,label,values,value){return `<label>${label}<select name="${name}">${values.map(v=>`<option ${v===value?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`}
function taskDialog(id,prefill={}){const t=id?state.tasks.find(t=>t.id===id):null;if(id&&!t)return;const data=t||{title:'',owner:'Alex Morgan',due:day(1),project:ui.project!=='All projects'?ui.project:'Website launch',status:'Backlog',priority:'Medium',description:'',...prefill};dialog(t?'Task details':'Give the next step a home',`<form id="task-form"><label>Task title<input name="title" value="${esc(data.title)}" required maxlength="160" autofocus></label><div class="form-grid">${formSelect('owner','Owner',people,data.owner)}<label>Due date<input type="date" name="due" value="${data.due}" required></label>${formSelect('project','Project',projects,data.project)}${formSelect('status','Status',statuses,data.status)}${formSelect('priority','Priority',['Low','Medium','High'],data.priority)}</div><label>Description<textarea name="description" rows="3">${esc(data.description||'')}</textarea></label>${data.source?`<button class="source-chip" type="button" data-action="source" data-type="${data.source.type}" data-id="${data.source.id}">${icon('link',15)}Open originating ${data.source.type==='chat'?'message':data.source.type==='docs'?'document':'meeting'}</button>`:''}${t?`<h3>Checklist</h3>${t.checklist.map((c,i)=>`<label class="check-label"><input type="checkbox" name="check-${i}" ${c.done?'checked':''}>${esc(c.text)}</label>`).join('')}<label>Add checklist item<input name="newChecklist" placeholder="A smaller next step"></label><h3>Comments</h3>${t.comments.map(c=>`<p class="task-comment"><b>${esc(c.author)}</b> ${esc(c.body)}</p>`).join('')}<label>Add a comment<textarea name="comment" rows="2" placeholder="Share useful context…"></textarea></label>`:''}<div class="form-actions">${btn('Cancel','close','quiet')}<button class="btn primary" type="submit">${t?'Save changes':'Create task'} ${icon('arrow',16)}</button></div></form>`);overlay.querySelector('dialog').classList.add('inspector');document.querySelector('#task-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),d=Object.fromEntries(['title','owner','due','project','status','priority','description'].map(k=>[k,f.get(k)]));if(!d.title.trim())return;if(t){d.checklist=t.checklist.map((c,i)=>({...c,done:f.has('check-'+i)}));if(f.get('newChecklist').trim())d.checklist.push({text:f.get('newChecklist').trim(),done:false});if(f.get('comment').trim())t.comments.push({author:state.profile,body:f.get('comment').trim()});updateTask(t.id,d)}else{let task=createTask({...d,source:data.source});if(prefill.meetingId){state.meetings.find(m=>m.id===prefill.meetingId).actionTaskIds.push(task.id)}if(prefill.intent)state.applied.push(prefill.intent)}persist();closeDialog();render();toast(t?'Task updated everywhere.':'Task created. Your plan is up to date.')};}
function eventDialog(id,prefill={}){const original=state.events.find(e=>e.id===id),e=original||{title:'',date:ui.calDate,time:'15:00',duration:30,attendees:['Alex Morgan','Maya Chen','Jordan Lee'],description:'',...prefill};dialog(original?'Event details':'Make time for what’s next',`<form id="event-form"><label>Title<input name="title" value="${esc(e.title)}" required maxlength="160" autofocus></label><div class="form-grid"><label>Date<input type="date" name="date" value="${e.date}" required></label><label>Time<input type="time" name="time" value="${e.time}" required></label>${formSelect('duration','Duration (minutes)',[15,30,45,60,90],e.duration)}</div><p class="muted small-text">${Intl.DateTimeFormat().resolvedOptions().timeZone}</p><fieldset><legend>Attendees</legend><div class="attendee-options">${people.map(n=>`<label class="check-label"><input type="checkbox" name="attendees" value="${n}" ${e.attendees.includes(n)?'checked':''}>${n}</label>`).join('')}</div></fieldset><label>Description<textarea name="description" rows="3">${esc(e.description)}</textarea></label><p id="event-warning" class="form-error" role="status"></p>${original?.meetingId?btn('Open meeting, notes & tasks','source','source-chip','meetings',`data-type="meetings" data-id="${original.meetingId}"`):''}<div class="form-actions">${btn('Cancel','close','quiet')}<button class="btn primary" type="submit">${original?'Save changes':'Approve & create event'}</button></div></form>`);document.querySelector('#event-form').onsubmit=ev=>{ev.preventDefault();let f=new FormData(ev.target),d={title:f.get('title').trim(),date:f.get('date'),time:f.get('time'),duration:Number(f.get('duration')),attendees:f.getAll('attendees'),description:f.get('description')};if(!d.title)return;let mins=t=>Number(t.split(':')[0])*60+Number(t.split(':')[1]);let conflict=state.events.find(x=>x.id!==id&&x.date===d.date&&mins(x.time)<mins(d.time)+d.duration&&mins(d.time)<mins(x.time)+x.duration);if(conflict){document.querySelector('#event-warning').textContent=`This overlaps “${conflict.title}”. Choose another time.`;return}if(original){Object.assign(original,d);activity('Meeting updated: '+d.title,d.date+' at '+time(d.time),'meetings',original.meetingId||'mt1')}else{let created=createEvent(d);if(prefill.intent)(state.actionRefs??={})[prefill.intent]=created.id}if(prefill.intent&&!state.applied.includes(prefill.intent))state.applied.push(prefill.intent);persist();closeDialog();render();toast(original?'Event and linked meeting updated.':'Event added to your local calendar.')};}
function threadDialog(id){const m=state.messages.find(m=>m.id===id);dialog('Thread · '+(m.channel.includes(' ')?m.channel:'#'+m.channel),`<div class="thread-source">${avatar(m.author)}<div><b>${m.author}</b><p>${esc(m.body)}</p></div></div><div class="thread-replies">${m.replies.map(r=>`<div>${avatar(r.author,true)}<span><b>${esc(r.author)}</b><p>${esc(r.body)}</p></span></div>`).join('')}</div><form id="thread-form"><label>Reply<textarea name="body" placeholder="Add to the conversation…" required autofocus></textarea></label><div class="form-actions"><button class="btn primary" type="submit">Reply ${icon('send',16)}</button></div></form>`);overlay.querySelector('dialog').classList.add('inspector');document.querySelector('#thread-form').onsubmit=e=>{e.preventDefault();let body=new FormData(e.target).get('body').trim();if(!body)return;m.replies.push({author:state.profile,body});persist();render();threadDialog(id)}}
function searchDialog(){dialog('Find your next step',`<label class="command-input">${icon('search',20)}<input id="command-query" placeholder="Search tasks, messages, docs, meetings, people…" aria-label="Search workspace" autofocus autocomplete="off"></label><div id="search-results" role="listbox" aria-label="Search results"></div><div class="command-hint">↑ ↓ to navigate <span>↵ to open</span><span>esc to close</span></div>`,true);let input=document.querySelector('#command-query'),index=0,results=[];const resultsEl=document.querySelector('#search-results');function update(){let q=input.value.toLowerCase();results=[...state.tasks.map(t=>({group:'Tasks',title:t.title,detail:t.project,type:'task',id:t.id})),...state.docs.map(d=>({group:'Documents',title:d.title,detail:'Workspace knowledge',type:'docs',id:d.id})),...state.events.filter(e=>e.meetingId).map(e=>({group:'Meetings',title:e.title,detail:fmt(e.date)+' · '+time(e.time),type:'meetings',id:e.meetingId})),...state.messages.map(m=>({group:'Messages',title:m.body,detail:m.author+' · '+m.channel,type:'chat',id:m.id})),...people.map(n=>({group:'People',title:n,detail:'Demo teammate · Open conversation',type:'chat',id:n}))].filter(r=>(r.title+' '+r.detail).toLowerCase().includes(q)).slice(0,q?30:8);index=0;paint()}function paint(){let group='';resultsEl.innerHTML=results.map((r,i)=>{let h=group!==r.group?`<div class="search-group">${r.group}</div>`:'';group=r.group;return h+`<button class="search-result ${i===index?'selected':''}" role="option" aria-selected="${i===index}" data-index="${i}">${icon(r.type==='task'?'projects':r.type,18)}<span><b>${esc(r.title)}</b><small>${esc(r.detail)}</small></span>${icon('arrow',15)}</button>`}).join('')||'<div class="empty">No results. Try “launch”, “copy”, or “Maya”.</div>';resultsEl.querySelector('.selected')?.scrollIntoView({block:'nearest'})}input.oninput=update;input.onkeydown=e=>{if(['ArrowDown','ArrowUp','Enter'].includes(e.key)){e.preventDefault();if(!results.length)return;if(e.key==='Enter'){let r=results[index];closeDialog();go(r.type,r.id)}else{index=(index+(e.key==='ArrowDown'?1:-1)+results.length)%results.length;paint()}}};resultsEl.onclick=e=>{let b=e.target.closest('[data-index]');if(b){let r=results[Number(b.dataset.index)];closeDialog();go(r.type,r.id)}};update()}
function notificationDialog(){dialog('You’re in the loop',`<div class="notification-head"><span>${unread()} unread updates</span>${btn('Mark all read','read-all','text')}</div>${state.activity.slice(0,8).map(a=>`<button class="notification-row ${a.read?'read':''}" data-action="activity-open" data-id="${a.id}">${icon(a.type==='task'?'projects':a.type,18)}<span><strong>${esc(a.title)}</strong><small>${esc(a.detail)}</small></span>${!a.read?'<i class="unread-dot"></i>':''}</button>`).join('')}`)}
function aiIntent(id){ui.ai=id;go('ai')}
function reviewAI(intent){if(state.applied.includes(intent)){toast('This action is already applied.');return}if(intent==='schedule')eventDialog(null,{title:'Launch copy review',...scheduleProposal(),duration:30,description:'Review revised onboarding copy and confirm launch readiness.',intent});if(intent==='tasks'){let m=state.meetings.find(m=>m.id==='mt1');if(m.actionTaskIds.length){toast('This follow-up already has a task.');taskDialog(m.actionTaskIds[0]);return}taskDialog(null,{title:'Validate the mobile onboarding flow',project:'Product onboarding',source:{type:'meetings',id:'mt1'},meetingId:'mt1',intent})}if(intent==='draft'){dialog('Review your team update',`<form id="draft-form"><span class="badge">Awaiting review · Local post to #launch</span><label>Message<textarea name="body" rows="7" required autofocus>Quick launch update: the visual direction is ready for approval. ${state.tasks.some(t=>t.source?.id==='m1')?'The onboarding copy now has an owner.':'We still need an owner for the onboarding copy.'} Jordan is ready to integrate the final copy. Let’s use our launch review to confirm the remaining next steps.</textarea></label><div class="form-actions">${btn('Cancel','close','quiet')}<button class="btn primary" type="submit">Confirm & post locally</button></div></form>`);document.querySelector('#draft-form').onsubmit=e=>{e.preventDefault();if(state.applied.includes(intent))return;let text=new FormData(e.target).get('body').trim();if(!text)return;sendMessage('launch',text);state.applied.push(intent);activity('AI-assisted update posted to #launch','Reviewed and confirmed by '+state.profile,'chat',state.messages.at(-1).id);persist();closeDialog();render();toast('Your reviewed update is now in #launch.')}}}
function room(){const m=state.meetings.find(m=>m.id===ui.meeting),e=state.events.find(e=>e.id===m.eventId);dialog('Meeting room preview',`<div class="room-label"><span class="badge">Simulation · No camera or microphone access</span><time id="call-timer">00:00</time></div><div class="room-grid">${e.attendees.map(n=>`<div class="participant">${avatar(n)}<span>${n}</span><small>Demo participant</small></div>`).join('')}</div><h3>${esc(e.title)} · Agenda</h3><ol>${m.agenda.map(a=>`<li>${esc(a)}</li>`).join('')}</ol><div class="room-controls">${btn('Mic off','room-mic','quiet','mic')}${btn('Camera off','room-camera','quiet','meetings')}${btn('Leave preview','close','danger','logout')}</div>`,true);let seconds=0;let timer=setInterval(()=>{seconds++;let t=document.querySelector('#call-timer');if(t)t.textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`},1000);dialogCleanup=()=>clearInterval(timer)}
function sendMessage(channel,body){state.messages.push({id:uid('m'),channel,author:state.profile,time:new Date().toLocaleTimeString([],{hour:'numeric',minute:'2-digit'}),body,reactions:[],saved:false,replies:[]});state.drafts[channel]='';persist()}
function docComments(){let d=state.docs.find(x=>x.id===ui.doc);dialog('Comments · '+esc(d.title),`<div>${(state.docComments[d.id]||[]).map(c=>`<p class="task-comment"><b>${esc(c.author)}</b><br>${esc(c.body)}</p>`).join('')||'<p class="muted">Leave useful context for the next person.</p>'}</div><form id="comment-form"><label>Comment<textarea name="body" required autofocus></textarea></label><div class="form-actions"><button class="btn primary">Add comment</button></div></form>`);document.querySelector('#comment-form').onsubmit=e=>{e.preventDefault();let body=new FormData(e.target).get('body').trim();if(!body)return;(state.docComments[d.id]??=[]).push({author:state.profile,body});activity('Comment added to '+d.title,body,'docs',d.id);persist();render();docComments()}}
function landing(){return landingPage(home,modules)}
async function waitlist(selectedPlan='team'){dialog('A more connected workday starts here.',`<p class="muted">${window.LOOP_WAITLIST_ENDPOINT?'Leave your details to join the Loop waitlist.':'Preview form · Details are saved only in this browser. This does not join a real waitlist.'}</p><form id="waitlist-form"><label>Plan of interest<select name="plan">${pricingConfig.plans.map(p=>`<option value="${p.id}" ${p.id===selectedPlan?'selected':''}>${p.name} · proposed plan</option>`).join('')}</select></label><label>Work email <span class="required">*</span><input type="email" name="email" required aria-describedby="waitlist-status" autocomplete="email" placeholder="you@company.com" autofocus></label><div class="form-grid"><label>Name <span class="muted">(optional)</span><input name="name" autocomplete="name"></label><label>Company <span class="muted">(optional)</span><input name="company" autocomplete="organization"></label></div>${formSelect('teamSize','Team size',['Just me','2–10','11–50','51–200','201–1,000','1,000+'],'2–10')}<label>What tools does your team use? <span class="muted">(optional)</span><input name="tools" placeholder="Chat, docs, calendars…"></label><label class="check-label consent"><input type="checkbox" name="consent" required aria-describedby="waitlist-status"> <span>${window.LOOP_WAITLIST_ENDPOINT?'I agree to share these details with Loop and receive updates about access.':'I understand this preview saves my details in this browser only.'}</span></label><p id="waitlist-status" role="status" aria-live="polite"></p><button type="submit" class="btn primary full">${window.LOOP_WAITLIST_ENDPOINT?'Join the waitlist':'Save preview entry'} ${icon('arrow',17)}</button></form>`);document.querySelector('#waitlist-form').onsubmit=async e=>{e.preventDefault();let f=e.target,data=Object.fromEntries(new FormData(f));data.email=data.email.trim().toLowerCase();let status=document.querySelector('#waitlist-status'),button=f.querySelector('[type="submit"]');button.disabled=true;button.textContent='Submitting…';try{let result=await submitWaitlist(data,{endpoint:window.LOOP_WAITLIST_ENDPOINT||''});status.textContent=result.message;if(result.status==='duplicate'){status.className='form-error';return}status.className='success-text';f.querySelectorAll('input,select').forEach(x=>x.disabled=true);button.hidden=true}catch(err){status.textContent=err.message||'We couldn’t save your entry. Please try again.';status.className='form-error'}finally{button.disabled=false;button.textContent=window.LOOP_WAITLIST_ENDPOINT?'Join the waitlist':'Save preview entry'}}}
const tourSteps=[['Your day, brought into focus','Start with the daily brief. The launch copy needs an owner.','home'],['Pick up the conversation','In #launch, use Create task below Maya’s message. Choose an owner and due date.','chat'],['A shared plan','Your new task appears here and on the owner’s Home view. Open it to change its status.','projects'],['Keep the momentum','Generate the prepared summary, then review and approve a follow-up task.','meetings'],['A little coordination','Ask Loop AI to find a review time. Review the suggestion before it is applied.','ai'],['The whole team stays in the loop','Confirmed actions appear in Activity. Explore freely, or return to the landing page using the Loop mark.','activity']];
function tourHtml(){let t=tourSteps[ui.tour];return `<aside class="tour-card" aria-label="Guided tour"><div><span>YOUR QUICK TOUR · ${ui.tour+1} / ${tourSteps.length}</span>${ib('close','End tour','end-tour')}</div><h3>${t[0]}</h3><p>${t[1]}</p><footer>${btn('End tour','end-tour','text')}${btn(ui.tour===tourSteps.length-1?'Finish':'Next','next-tour','primary','arrow')}</footer></aside>`}
document.addEventListener('click',e=>{let check=e.target.closest('#doc-editor [data-check]');if(check&&e.clientX<check.getBoundingClientRect().left+25){check.dataset.check=String(check.dataset.check!=='true');check.querySelector('.doc-check-toggle')?.setAttribute('aria-checked',check.dataset.check);document.querySelector('#doc-editor').dispatchEvent(new Event('input'));return}const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;if(b.closest('form')&&b.type!=='submit')e.preventDefault();if(a.startsWith('nav-')){closeDialog();go(a.slice(4));return}switch(a){
case 'explore':go('home');break;case 'landing-module':go(id);break;case 'sidebar':ui.side=!ui.side;render();break;case 'waitlist':waitlist(b.dataset.plan||'team');break;case 'appearance':dialog('Your point of view',appearancePanel());break;case 'close':closeDialog(true);break;case 'search':searchDialog();break;case 'notifications':notificationDialog();break;case 'launch-source':go('chat','m1');break;case 'channel':ui.channel=id;state.activity.filter(a=>a.type==='chat'&&state.messages.find(m=>m.id===a.ref)?.channel===id).forEach(a=>a.read=true);persist();render();break;case 'doc':closeDialog();go('docs',id);break;case 'meeting':go('meetings',id);break;case 'project':closeDialog();ui.project=id;go('projects');break;case 'source':closeDialog();if(b.dataset.type==='projects'){ui.project=id;go('projects')}else go(b.dataset.type,id);break;case 'my-day':ui.homeTeam=false;render();break;case 'team-day':ui.homeTeam=true;render();break;
case 'task':taskDialog(id);break;case 'new-task':taskDialog(null,{...(b.dataset.status?{status:b.dataset.status}:{})});break;case 'toggle-task':{let t=state.tasks.find(t=>t.id===id),old=t.status;updateTask(id,{status:t.status==='Done'?'Backlog':'Done'});render();toast(t.status==='Done'?'Task completed. Nice progress.':'Task reopened.',()=>{updateTask(id,{status:old})});break}
case 'message-task':{let existing=state.tasks.find(t=>t.source?.type==='chat'&&t.source.id===id);if(existing){taskDialog(existing.id);break}let m=state.messages.find(m=>m.id===id);taskDialog(null,{title:id==='m1'?'Revise the onboarding copy':m.body.slice(0,100),source:{type:'chat',id},description:m.body});break}
case 'react':{let m=state.messages.find(m=>m.id===id);m.reactions=m.reactions.includes('Alex Morgan')?m.reactions.filter(n=>n!=='Alex Morgan'):[...m.reactions,'Alex Morgan'];persist();render();break}
case 'save-message':{let m=state.messages.find(m=>m.id===id);m.saved=!m.saved;persist();render();toast(m.saved?'Message saved.':'Message removed from saved.');break}
case 'thread':threadDialog(id);break;case 'link-message':dialog('Connect the context',`<p class="muted">Link this message to a document or project.</p>${state.docs.map(d=>btn(d.title,'add-message-link','link-option','docs',`data-message="${id}" data-id="${d.id}" data-type="docs"`)).join('')}${projects.map(p=>btn(p,'add-message-link','link-option','projects',`data-message="${id}" data-id="${p}" data-type="projects"`)).join('')}`);break;
case 'add-message-link':{let m=state.messages.find(m=>m.id===b.dataset.message);m.links??=[];if(!m.links.some(l=>l.id===id))m.links.push({type:b.dataset.type,id,label:b.dataset.type==='docs'?state.docs.find(d=>d.id===id).title:id});persist();closeDialog();render();toast('Context linked.');break}
case 'summarize-chat':{let msgs=state.messages.filter(m=>m.channel===ui.channel);dialog('Conversation, in focus',`<div class="eyebrow">${icon('ai',17)} PREPARED LOCAL SUMMARY</div><p>${ui.channel==='launch'?'Maya has finished the launch direction. The onboarding copy needs a first pass, and Jordan is waiting on it to finish the welcome screen. Priya can provide customer language from research.':msgs.length?'Recent discussion: '+esc(msgs.slice(-2).map(m=>m.author.split(' ')[0]+': '+m.body).join(' ')):'There are no messages to summarize yet.'}</p><div class="form-actions">${btn('Open launch brief','source','quiet','docs','data-type="docs" data-id="d3"')}${btn('Done','close','primary')}</div>`);break}
case 'board':ui.board=true;render();break;case 'list':ui.board=false;render();break;
case 'event':eventDialog(id);break;case 'new-event':eventDialog(null,{date:b.dataset.date||ui.calDate,time:b.dataset.time||'15:00'});break;case 'cal-view':ui.calView=id;render();break;case 'cal-date':ui.calDate=id;render();break;case 'cal-today':ui.calDate=day();render();break;case 'cal-prev':case 'cal-next':{let d=new Date(ui.calDate+'T12:00:00'),sign=a==='cal-prev'?-1:1;if(ui.calView==='month')d.setMonth(d.getMonth()+sign);else d.setDate(d.getDate()+sign*(ui.calView==='week'?7:1));ui.calDate=localDate(d);render();break}
case 'new-doc':dialog('A new home for an idea',`<form id="new-doc-form"><label>Document title<input name="title" required autofocus placeholder="Untitled document"></label><div class="form-actions"><button class="btn primary" type="submit">Create document</button></div></form>`);document.querySelector('#new-doc-form').onsubmit=e=>{e.preventDefault();let title=new FormData(e.target).get('title').trim();if(!title)return;let id=uid('d');state.docs.push({id,title,content:'<p>Start with a thought. Give it room to grow.</p>',favorite:false,parent:null});persist();closeDialog();go('docs',id)};break;
case 'favorite-doc':{let d=state.docs.find(d=>d.id===id);d.favorite=!d.favorite;persist();render();break}
case 'doc-task':{let selection=window.getSelection()?.toString();taskDialog(null,{title:selection||'Revise the onboarding copy',source:{type:'docs',id:ui.doc}});break}
case 'doc-comments':docComments();break;case 'format':{let editor=document.querySelector('#doc-editor');editor.focus();if(id==='h2'||id==='blockquote')document.execCommand('formatBlock',false,id);else if(id==='checklist')document.execCommand('insertHTML',false,'<p data-check="false">Checklist item</p>');else if(id==='link'){let selection=window.getSelection(),range=selection.rangeCount?selection.getRangeAt(0).cloneRange():null;dialog('Add a link',`<form id="link-form"><label>Destination URL<input type="url" name="url" required placeholder="https://…" autofocus></label><div class="form-actions"><button class="btn primary">Insert link</button></div></form>`);document.querySelector('#link-form').onsubmit=e=>{e.preventDefault();let url=new FormData(e.target).get('url');if(!/^https?:\/\//i.test(url))return;closeDialog();editor.focus();if(range){let s=window.getSelection();s.removeAllRanges();s.addRange(range)}document.execCommand('createLink',false,url);editor.dispatchEvent(new Event('input'))}}else document.execCommand(id,false);editor.dispatchEvent(new Event('input'));break}
case 'generate-summary':{let m=state.meetings.find(m=>m.id===ui.meeting);dialog('Preparing your summary',`<p>Connecting the prepared notes to your next steps…</p><div class="loading-line"></div>${btn('Cancel','close','quiet')}`);let timer=setTimeout(()=>{dialogCleanup=null;m.summary=true;persist();closeDialog();render();toast('Sample summary ready for review.')},700);dialogCleanup=()=>clearTimeout(timer);break}
case 'meeting-task':{let m=state.meetings.find(m=>m.id===ui.meeting);if(m.actionTaskIds.length)taskDialog(m.actionTaskIds[0]);else taskDialog(null,{title:'Validate the mobile onboarding flow',source:{type:'meetings',id:m.id},project:'Product onboarding',meetingId:m.id});break}
case 'room':room();break;case 'room-mic':case 'room-camera':{let on=b.dataset.on==='true';b.dataset.on=String(!on);b.classList.toggle('primary',!on);b.innerHTML=icon(a==='room-mic'?'mic':'meetings',17)+(a==='room-mic'?'Mic':'Camera')+(on?' off':' on · simulated');break}
case 'activity-all':ui.activityUnread=false;render();break;case 'activity-unread':ui.activityUnread=true;render();break;case 'read-all':state.activity.forEach(a=>a.read=true);persist();render();if(overlay.querySelector('dialog'))notificationDialog();break;case 'read-one':{let a=state.activity.find(a=>a.id===id);a.read=!a.read;persist();render();break}case 'activity-open':{let a=state.activity.find(a=>a.id===id);a.read=true;persist();closeDialog();go(a.type,a.ref);break}
case 'focus-ai':aiIntent('focus');break;case 'schedule-ai':aiIntent('schedule');break;case 'ai-intent':aiIntent(id);break;case 'ai-review':reviewAI(id);break;
case 'quick-create':dialog('Make something happen',`<div class="quick-grid">${[['new-task','projects','New task','Give work an owner.'],['new-doc','docs','New document','Give an idea a home.'],['new-event','calendar','New event','Make time for your team.'],['new-message','chat','New message','Start a conversation.']].map(([a,i,t,p])=>`<button data-action="${a}">${icon(i,24)}<strong>${t}</strong><small>${p}</small></button>`).join('')}</div>`);break;case 'new-message':closeDialog();go('chat');document.querySelector('.composer textarea')?.focus();break;
case 'integration':dialog(esc(id)+' · connection preview',`<span class="badge">Planned integration · Not connected</span><p>${id==='Slack'?'Bring conversations and source messages into a shared workspace. You would choose which channels to include.':id==='Google Calendar'?'View availability and keep approved events synchronized. You would choose a calendar before granting access.':'Keep documents discoverable alongside the conversations and projects they support. You would select the files to share.'}</p><p class="muted">This prototype uses seeded local data. No account is connected and no external service is accessed.</p><div class="form-actions">${btn('Got it','close','primary')}</div>`);break;
case 'reset':dialog('Start fresh?',`<p>This will replace local messages, tasks, events, document edits, and preferences with the original Loop demo. Preview waitlist entries are kept separately.</p><div class="form-actions">${btn('Keep my workspace','close','quiet')}${btn('Reset demo data','confirm-reset','danger','undo')}</div>`);break;case 'confirm-reset':reset();ui.calDate=state.demoDate;ui.doc='d3';ui.meeting='mt1';ui.ai=null;ui.homeTeam=false;ui.side=true;ui.query='';ui.owner='Everyone';ui.status='All statuses';ui.project='All projects';closeDialog();go('home');toast('Welcome back to a fresh Loop.');break;
case 'tour':ui.tour=0;go('home');break;case 'end-tour':ui.tour=-1;render();break;case 'next-tour':ui.tour++;if(ui.tour>=tourSteps.length){ui.tour=-1;render()}else{if(ui.tour===1)ui.channel='launch';if(ui.tour===3)ui.meeting='mt1';go(tourSteps[ui.tour][2])}break;
}});
document.addEventListener('invalid',e=>{if(e.target.closest('#waitlist-form')){const status=document.querySelector('#waitlist-status');status.className='form-error';status.textContent=!e.target.closest('form').querySelector('[name=email]').validity.valid?'Enter a valid work email address.':'Please confirm the consent statement.'}},true);
document.addEventListener('submit',e=>{if(e.target.id==='message-form'){e.preventDefault();let body=new FormData(e.target).get('body').trim();if(body){sendMessage(ui.channel,body);render();document.querySelector('.composer textarea')?.focus()}}if(e.target.id==='ai-form'){e.preventDefault();let q=new FormData(e.target).get('prompt').toLowerCase();let intent=/time|schedule|review time/.test(q)?'schedule':/block/.test(q)?'blockers':/summar/.test(q)?'summary':/task|action/.test(q)?'tasks':/draft|update/.test(q)?'draft':/focus|today|priorit/.test(q)?'focus':'unknown';aiIntent(intent)}if(e.target.id==='settings-form'){e.preventDefault();let f=new FormData(e.target);state.profile=f.get('name').trim()||'Alex Morgan';state.reduced=f.has('reduced');state.notifications=f.has('notifications');persist();render();toast('Preferences saved.')}});
document.addEventListener('input',e=>{if(e.target.matches('.composer textarea')){state.drafts[ui.channel]=e.target.value;persist()}if(e.target.id==='doc-title'){let title=e.target.value.trim();if(title){state.docs.find(d=>d.id===ui.doc).title=title;persist()}}if(e.target.id==='meeting-notes'){state.meetings.find(m=>m.id===ui.meeting).notes=e.target.value;persist()}if(e.target.id==='task-search'){let pos=e.target.selectionStart;ui.query=e.target.value;render();let input=document.querySelector('#task-search');input.focus();input.setSelectionRange(pos,pos)}if(e.target.id==='channel-filter'){let q=e.target.value.toLowerCase();document.querySelectorAll('.context-sidebar [data-action="channel"]').forEach(el=>el.hidden=!el.dataset.id.toLowerCase().includes(q))}});
document.addEventListener('change',e=>{if(e.target.id==='status-filter'){ui.status=e.target.value;render()}if(e.target.id==='owner-filter'){ui.owner=e.target.value;render()}if(e.target.id==='cal-team'){ui.calTeam=e.target.checked;render()}if(e.target.id==='cal-focus'){ui.calFocus=e.target.checked;render()}});
document.addEventListener('keydown',e=>{if(e.target.matches('#doc-editor [data-check]')&&e.key===' '){e.preventDefault();e.target.dataset.check=String(e.target.dataset.check!=='true');e.target.setAttribute('aria-checked',e.target.dataset.check);document.querySelector('#doc-editor').dispatchEvent(new Event('input'))}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();searchDialog()}if(e.target.matches('.composer textarea')&&e.key==='Enter'&&!e.shiftKey){e.preventDefault();e.target.form.requestSubmit()}});
window.addEventListener('hashchange',route);window.addEventListener('popstate',route);route();
